#include <ctype.h>

int main()
{
    char line[256];
    int cnt[26] = {0}, i;
    if (fgets(line, sizeof(line), stdin) == NULL)
        return 0;
    for (i = 0; line[i] != '\0'; i++)
        if (isalpha((unsigned char)line[i]))
            cnt[tolower((unsigned char)line[i]) - 'a']++;
    for (i = 0; i < 26; i++)
        if (cnt[i] > 0)
            printf("%c %d\n", 'a' + i, cnt[i]);
    return 0;
}

